import json
import sys

files = {
    'healthcare': 'healthcare_tasks.json',
    'bank': 'bank_tasks.json',
    'hotel': 'hotel_tasks.json',
    'library': 'library_tasks.json'
}

for domain, fname in files.items():
    try:
        with open(fname, 'r') as f:
            data = json.load(f)

        # Get first action key
        first_action = list(data.keys())[0]
        tasks = data[first_action]

        # Find a false task
        false_task = None
        for task in tasks:
            if task.get('action_should_succeed') == False:
                false_task = task
                break

        if false_task:
            print(f"\n=== {domain.upper()} (FALSE TASK) ===")
            print(f"Action: {first_action}")
            print(f"Keys in task: {list(false_task.keys())}")
            # Print user prompt and key fields
            if 'user_prompt' in false_task:
                print(f"user_prompt: {false_task['user_prompt'][:100]}...")
            if 'action_should_succeed' in false_task:
                print(f"action_should_succeed: {false_task['action_should_succeed']}")
            if 'constraints' in false_task:
                print(f"constraints: {false_task['constraints']}")
            if 'constraint_parameters' in false_task:
                print(f"constraint_parameters: {false_task['constraint_parameters']}")
            if 'user_instruction' in false_task:
                print(f"user_instruction: {false_task['user_instruction'][:100]}...")
        else:
            print(f"\n=== {domain.upper()} ===")
            print("No false task found in first action, showing true task structure")
            print(f"Action: {first_action}")
            print(f"Keys in task: {list(tasks[0].keys())}")

    except Exception as e:
        print(f"Error reading {fname}: {e}")

